extern const unsigned char anypsp_ui_regular_font[];
extern const std::size_t anypsp_ui_regular_font_size;
extern const unsigned char anypsp_ui_bold_font[];
extern const std::size_t anypsp_ui_bold_font_size;
extern const unsigned char anypsp_ui_strings[];
extern const std::size_t anypsp_ui_strings_size;

namespace anypsp::menu {
namespace {

using anyui::Icon;
using anyui::Row;
using anyui::RowKind;
namespace pad = pspweb::pad;

constexpr int kVisibleRows = 13;
constexpr int kRepeatDelay = 18;
constexpr int kRepeatEvery = 4;
constexpr std::array<int, 4> kUiScales = {75, 100, 125, 150};
constexpr int kActions = static_cast<int>(input::Action::Count);

bool selectable(const Row &r) { return r.kind != RowKind::Header && r.kind != RowKind::Info; }

bool starts_with(const std::string &s, std::string_view prefix) { return s.rfind(prefix, 0) == 0; }

int id_number(const std::string &id) {
    const auto dot = id.rfind('.');
    return dot == std::string::npos ? -1 : std::atoi(id.c_str() + dot + 1);
}

std::string bindings(const std::vector<int> &codes, bool keyboard) {
    std::string out;
    for (const int c : codes) out += (out.empty() ? "" : ", ") + (keyboard ? input::key_name(c) : std::string(input::button_name(c)));
    return out;
}

} // namespace

anyui::Strings &strings() {
    static anyui::Strings table(std::string_view(reinterpret_cast<const char *>(anypsp_ui_strings), anypsp_ui_strings_size));
    return table;
}

const anyui::Font &regular_font() {
    static const anyui::Font font({anypsp_ui_regular_font, anypsp_ui_regular_font_size});
    return font;
}

const anyui::Font &bold_font() {
    static const anyui::Font font({anypsp_ui_bold_font, anypsp_ui_bold_font_size});
    return font;
}

std::string Menu::tr(std::string_view key) const {
    strings().set_language(map_.player().language);
    return strings().tr(key);
}

std::string Menu::fmt(std::string_view key, std::initializer_list<std::string_view> args) const {
    strings().set_language(map_.player().language);
    return strings().fmt(key, args);
}

std::vector<Menu::TabInfo> Menu::tabs() const {
    // No Cheats tab: AnyPSP has no cheats yet.
    return {{Page::Game, "tab.game", Icon::Game},       {Page::Saves, "tab.saves", Icon::Card},
            {Page::Video, "tab.video", Icon::Video},    {Page::Audio, "tab.audio", Icon::Audio},
            {Page::Controls, "tab.controls", Icon::Controls}, {Page::Settings, "tab.settings", Icon::Settings}};
}

int Menu::tab_index() const {
    const Page root = page_ == Page::Capture ? Page::Controls : page_;
    const auto t = tabs();
    for (std::size_t i = 0; i < t.size(); ++i)
        if (t[i].page == root) return static_cast<int>(i);
    return 0;
}

void Menu::open() {
    open_ = true;
    page_ = Page::Game;
    rail_ = false;
    cursor_ = 0;
    confirm_.clear();
    message_.clear();
    ignore_held_ = true;  // buttons still held from opening the menu do nothing
}

void Menu::close_menu(std::vector<Action> &out) {
    open_ = false;
    out.push_back(Action::Close);
}

void Menu::go_tab(int index) {
    const auto t = tabs();
    const int n = static_cast<int>(t.size());
    page_ = t[static_cast<std::size_t>(((index % n) + n) % n)].page;
    cursor_ = 0;
    confirm_.clear();
    const auto r = rows();
    while (cursor_ < static_cast<int>(r.size()) && !selectable(r[static_cast<std::size_t>(cursor_)])) ++cursor_;
}

void Menu::move_cursor(int delta) {
    const auto r = rows();
    const int n = static_cast<int>(r.size());
    if (n == 0) return;
    const int dir = delta > 0 ? 1 : -1;
    for (int steps = std::abs(delta); steps > 0; --steps) {
        int next = cursor_;
        for (int k = 0; k < n; ++k) {
            next = (next + dir + n) % n;
            if (selectable(r[static_cast<std::size_t>(next)])) break;
        }
        if (std::abs(delta) > 1 && ((dir > 0 && next < cursor_) || (dir < 0 && next > cursor_))) break;
        cursor_ = next;
    }
    confirm_.clear();
}

std::uint32_t Menu::pressed_with_repeat(std::uint32_t held) {
    if (ignore_held_) {
        ignore_held_ = false;
        last_held_ = held;
        return 0;
    }
    std::uint32_t pressed = held & ~last_held_;
    if (held != 0 && held == last_held_) {
        if (++repeat_frames_ >= kRepeatDelay && (repeat_frames_ - kRepeatDelay) % kRepeatEvery == 0)
            pressed |= held & (pad::kUp | pad::kDown | pad::kLeft | pad::kRight);
    } else {
        repeat_frames_ = 0;
    }
    last_held_ = held;
    return pressed;
}

std::vector<Action> Menu::update(const MenuInput &in) {
    std::vector<Action> out;
    if (!open_) return out;
    const std::uint32_t press = pressed_with_repeat(in.pad);
    if (page_ == Page::Capture) {
        update_capture(in, out);
        return out;
    }
    const auto key = [&](int code) { return std::find(in.keys.begin(), in.keys.end(), code) != in.keys.end(); };
    if (in.menu) {
        close_menu(out);
        return out;
    }
    if (press) message_.clear();
    if (key(SDL_SCANCODE_TAB) || (press & (pad::kL | pad::kR))) {
        go_tab(tab_index() + ((key(SDL_SCANCODE_TAB) ? in.shift : (press & pad::kL) != 0) ? -1 : 1));
        return out;
    }
    if (rail_) {
        if (press & pad::kDown) go_tab(tab_index() + 1);
        if (press & pad::kUp) go_tab(tab_index() - 1);
        if (press & (pad::kCross | pad::kStart | pad::kRight)) rail_ = false;
        if (press & pad::kCircle) close_menu(out);
        return out;
    }
    const auto all = rows();
    if (!all.empty()) {
        if (press & pad::kDown) move_cursor(1);
        if (press & pad::kUp) move_cursor(-1);
        if (key(SDL_SCANCODE_PAGEDOWN)) move_cursor(kVisibleRows);
        if (key(SDL_SCANCODE_PAGEUP)) move_cursor(-kVisibleRows);
    }
    cursor_ = std::clamp(cursor_, 0, std::max(static_cast<int>(all.size()) - 1, 0));
    if (press & pad::kCircle) {
        close_menu(out);
        return out;
    }
    if (all.empty()) {
        if (press & pad::kLeft) rail_ = true;
        return out;
    }
    const Row &row = all[static_cast<std::size_t>(cursor_)];
    if (press & (pad::kCross | pad::kStart)) {
        activate(row, out);
    } else if (press & pad::kRight) {
        step(row, 1, out);
    } else if (press & pad::kLeft) {
        if (row.kind == RowKind::Choice || row.kind == RowKind::Slider || row.kind == RowKind::Toggle) step(row, -1, out);
        else rail_ = true;
    }
    return out;
}

void Menu::activate(const Row &row, std::vector<Action> &out) {
    const std::string &id = row.id;
    if (id == "game.resume") {
        close_menu(out);
    } else if (id == "game.reset" || id == "game.exit") {
        if (confirm_ != id) {
            confirm_ = id;
            say(tr(id == "game.reset" ? "game.reset.confirm" : "game.exit.confirm"));
            return;
        }
        confirm_.clear();
        open_ = false;
        out.push_back(id == "game.reset" ? Action::Reset : Action::Exit);
        out.push_back(Action::Close);
    } else if (row.kind == RowKind::Choice || row.kind == RowKind::Toggle || row.kind == RowKind::Slider) {
        step(row, 1, out);
    } else if (starts_with(id, "bind.")) {
        capture_ = static_cast<input::Action>(id_number(id));
        page_ = Page::Capture;
    } else if (id == "controls.reset") {
        map_.reset_bindings();
        say(tr("controls.reset.done"));
        out.push_back(Action::SettingsChanged);
    }
}

void Menu::step(const Row &row, int dir, std::vector<Action> &out) {
    const std::string &id = row.id;
    input::PlayerSettings &p = map_.player();
    confirm_.clear();
    if (id == "video.scale") {
        map_.set_scale((map_.scale() - 1 + dir + 4) % 4 + 1);
        say(map_.scale() == running_scale_ ? tr("video.scale.now") : tr("video.scale.next"));
    } else if (id == "video.fullscreen") {
        fullscreen_ = !fullscreen_;
        out.push_back(Action::Fullscreen);
        return;
    } else if (id == "video.filter") {
        p.sharp = !p.sharp;
    } else if (id == "video.patches") {
        if (patches_ == nullptr) return;
        *patches_ = !*patches_;
        out.push_back(Action::DisplayChanged);
        return;
    } else if (display_ != nullptr && starts_with(id, "video.")) {
        display::Settings &d = *display_;
        const auto cycle = [dir](std::span<const int> allowed, int value) {
            const auto at = std::find(allowed.begin(), allowed.end(), value);
            const int n = static_cast<int>(allowed.size());
            const int i = at == allowed.end() ? 0 : static_cast<int>(at - allowed.begin());
            return allowed[static_cast<std::size_t>(((i + dir) % n + n) % n)];
        };
        if (id == "video.smoothing") d.smoothing = !d.smoothing;
        else if (id == "video.refresh") d.refresh = cycle(display::kRefreshRates, d.refresh);
        else if (id == "video.vrr") d.vrr = !d.vrr;
        else if (id == "video.sync") d.sync_to_monitor = !d.sync_to_monitor;
        else if (id == "video.menu_fps") d.menu_fps = cycle(display::kPauseFps, d.menu_fps);
        else if (id == "video.fps_cap") d.fps_cap = cycle(display::kFpsCaps, d.fps_cap);
        else return;
        out.push_back(Action::DisplayChanged);
        return;
    } else if (id == "audio.volume") {
        const int next = std::clamp(p.volume + dir * 10, 0, 100);
        if (next == p.volume) return;
        p.volume = next;
    } else if (id == "audio.mute") {
        p.mute = !p.mute;
    } else if (id == "settings.language") {
        p.language = p.language == "en" ? "vi" : "en";
    } else if (id == "settings.theme") {
        p.light_theme = !p.light_theme;
    } else if (id == "settings.scale") {
        const auto at = std::find(kUiScales.begin(), kUiScales.end(), p.ui_scale);
        int i = at == kUiScales.end() ? 1 : static_cast<int>(at - kUiScales.begin());
        i = ((i + dir) % static_cast<int>(kUiScales.size()) + static_cast<int>(kUiScales.size())) % static_cast<int>(kUiScales.size());
        p.ui_scale = kUiScales[static_cast<std::size_t>(i)];
    } else if (id == "settings.motion") {
        p.reduce_motion = !p.reduce_motion;
    } else if (id == "settings.fps") {
        p.show_fps = !p.show_fps;
    } else {
        return;
    }
    out.push_back(Action::SettingsChanged);
}

void Menu::update_capture(const MenuInput &in, std::vector<Action> &out) {
    for (const int k : in.keys) {
        if (k == SDL_SCANCODE_ESCAPE) {
            say(tr("controls.cancelled"));
            page_ = Page::Controls;
            ignore_held_ = true;
            return;
        }
        const std::string swapped = map_.rebind(capture_, true, k);
        say(std::string(input::action_name(capture_)) + " = " + input::key_name(k) +
            (swapped.empty() ? "" : " (" + fmt("controls.swapped", {swapped}) + ")"));
        page_ = Page::Controls;
        ignore_held_ = true;  // the key just bound must not also act in the menu
        out.push_back(Action::SettingsChanged);
        return;
    }
    if (!in.buttons.empty()) {
        const int b = in.buttons.back();
        const std::string swapped = map_.rebind(capture_, false, b);
        say(std::string(input::action_name(capture_)) + " = " + input::button_name(b) +
            (swapped.empty() ? "" : " (" + fmt("controls.swapped", {swapped}) + ")"));
        page_ = Page::Controls;
        ignore_held_ = true;
        out.push_back(Action::SettingsChanged);
    }
}

std::vector<Action> Menu::click(anyui::Hit hit) {
    std::vector<Action> out;
    if (!open_) return out;
    using anyui::HitKind;
    message_.clear();
    if (page_ == Page::Capture) {
        if (hit.kind == HitKind::Outside || hit.kind == HitKind::Close) {
            say(tr("controls.cancelled"));
            page_ = Page::Controls;
        }
        return out;
    }
    switch (hit.kind) {
    case HitKind::Tab:
        go_tab(hit.index);
        rail_ = false;
        break;
    case HitKind::Close:
    case HitKind::Outside:
    case HitKind::Back: close_menu(out); break;
    case HitKind::Row:
    case HitKind::Decrease:
    case HitKind::Increase: {
        rail_ = false;
        const auto all = rows();
        if (hit.index < 0 || hit.index >= static_cast<int>(all.size())) break;
        const Row &row = all[static_cast<std::size_t>(hit.index)];
        if (!selectable(row)) break;
        if (cursor_ != hit.index) confirm_.clear();
        cursor_ = hit.index;
        if (hit.kind == HitKind::Decrease) step(row, -1, out);
        else if (hit.kind == HitKind::Increase) step(row, 1, out);
        else if (row.kind != RowKind::Choice && row.kind != RowKind::Slider) activate(row, out);
        break;
    }
    default: break;
    }
    return out;
}

std::string Menu::title() const {
    switch (page_) {
    case Page::Game: return tr("tab.game");
    case Page::Saves: return tr("tab.saves");
    case Page::Video: return tr("tab.video");
    case Page::Audio: return tr("tab.audio");
    case Page::Controls: return tr("tab.controls");
    case Page::Capture: return tr("controls.rebind") + " " + input::action_name(capture_);
    case Page::Settings: return tr("tab.settings");
    }
    return {};
}

std::string Menu::hint() const {
    if (rail_) return tr("hint.rail");
    if (page_ == Page::Capture) return tr("hint.capture");
    return tr("hint.page");
}

std::vector<Row> Menu::rows() const {
    std::vector<Row> out;
    const input::PlayerSettings &p = map_.player();
    const auto on_off = [&](bool on) { return tr(on ? "on" : "off"); };
    const auto toggle = [&](const char *id, bool on, Icon icon) {
        Row r;
        r.id = id;
        r.kind = RowKind::Toggle;
        r.label = tr(id);
        r.value = on_off(on);
        r.on = on;
        r.icon = icon;
        out.push_back(std::move(r));
    };
    const auto row = [&](const char *id, RowKind kind, std::string value, Icon icon) {
        Row r;
        r.id = id;
        r.kind = kind;
        r.label = tr(id);
        r.value = std::move(value);
        r.icon = icon;
        out.push_back(std::move(r));
        return &out.back();
    };
    switch (page_) {
    case Page::Game:
        row("game.resume", RowKind::Action, "", Icon::Resume);
        row("game.reset", RowKind::Action, confirm_ == "game.reset" ? tr("confirm") : "", Icon::Reset);
        row("game.exit", RowKind::Action, confirm_ == "game.exit" ? tr("confirm") : "", Icon::Exit)->danger = true;
        break;
    case Page::Saves:
        for (std::size_t i = 0; i < saves_.size(); ++i) {
            const SaveInfo &s = saves_[i];
            Row r;
            r.id = "save." + std::to_string(i);
            r.kind = RowKind::Action;
            r.label = s.title;
            r.detail = s.detail;
            if (!s.icon.empty()) r.thumb = {s.icon.data(), s.icon_width, s.icon_height};
            else r.icon = Icon::Card;
            out.push_back(std::move(r));
        }
        break;
    case Page::Video: {
        const int s = map_.scale();
        Row *scale = row("video.scale", RowKind::Choice,
                         std::to_string(s) + "x (" + std::to_string(480 * s) + "x" + std::to_string(272 * s) + ")", Icon::Video);
        if (s != running_scale_) scale->detail = tr("video.scale.next");
        toggle("video.fullscreen", fullscreen_, Icon::Video);
        row("video.filter", RowKind::Choice, tr(p.sharp ? "filter.sharp" : "filter.smooth"), Icon::Settings);
        if (display_ != nullptr) {
            const display::Settings &d = *display_;
            toggle("video.smoothing", d.smoothing, Icon::Video);
            row("video.refresh", RowKind::Choice, d.refresh == 0 ? tr("video.refresh.auto") : std::to_string(d.refresh) + " Hz", Icon::Video);
            toggle("video.vrr", d.vrr, Icon::Video);
            toggle("video.sync", d.sync_to_monitor, Icon::Video);
            row("video.menu_fps", RowKind::Choice, std::to_string(d.menu_fps), Icon::Video);
            row("video.fps_cap", RowKind::Choice, d.fps_cap == 0 ? tr("off") : std::to_string(d.fps_cap), Icon::Video);
        }
        if (patches_ != nullptr) toggle("video.patches", *patches_, Icon::Settings);
        else row("video.patches", RowKind::Info, tr("video.patches.none"), Icon::Settings);
        break;
    }
    case Page::Audio: {
        Row *v = row("audio.volume", RowKind::Slider, std::to_string(p.volume) + "%", Icon::Audio);
        v->level = static_cast<float>(p.volume) / 100.f;
        toggle("audio.mute", p.mute, Icon::Mute);
        break;
    }
    case Page::Controls:
    case Page::Capture:
        for (int i = 0; i < kActions; ++i) {
            if (i == 0) row("controls.buttons", RowKind::Header, "", Icon::None);
            if (i == static_cast<int>(input::Action::AnalogUp)) row("controls.analog", RowKind::Header, "", Icon::None);
            if (i == static_cast<int>(input::Action::Fullscreen)) row("controls.hotkeys", RowKind::Header, "", Icon::None);
            const auto a = static_cast<input::Action>(i);
            Row r;
            r.id = "bind." + std::to_string(i);
            r.kind = RowKind::Binding;
            r.label = a == input::Action::Menu ? tr("controls.menu") : a == input::Action::Fullscreen ? tr("video.fullscreen")
                                                                                                   : input::action_name(a);
            r.value = bindings(map_.keys(a), true);
            r.value2 = bindings(map_.buttons(a), false);
            if (a == input::Action::Menu) r.value2 = r.value2.empty() ? "Back+Start" : r.value2 + ", Back+Start";
            out.push_back(std::move(r));
        }
        row("controls.reset", RowKind::Action, "", Icon::Reset);
        break;
    case Page::Settings:
        row("settings.language", RowKind::Choice, tr(p.language == "vi" ? "language.vi" : "language.en"), Icon::Language);
        row("settings.theme", RowKind::Choice, tr(p.light_theme ? "theme.light" : "theme.dark"), Icon::Theme);
        row("settings.scale", RowKind::Choice, std::to_string(p.ui_scale) + "%", Icon::Video);
        toggle("settings.motion", p.reduce_motion, Icon::Resume);
        toggle("settings.fps", p.show_fps, Icon::Info);
        break;
    }
    return out;
}

anyui::Frame Menu::view() const {
    anyui::Frame f;
    f.brand = "AnyPSP";
    f.game = game_title_;
    for (const TabInfo &t : tabs()) f.tabs.push_back({t.id, tr(t.id), t.icon});
    f.tab = tab_index();
    f.rail_focus = rail_;
    f.hint = hint();
    f.message = message_;
    f.message_error = message_error_;
    anyui::Page &p = f.page;
    p.title = title();
    p.rows = rows();
    p.cursor = cursor_;
    if (page_ == Page::Saves) p.empty_text = tr("saves.none");
    if (page_ == Page::Controls || page_ == Page::Capture) {
        p.diagram = anyui::Diagram::Psp;
        if (cursor_ >= 0 && cursor_ < static_cast<int>(p.rows.size()) && starts_with(p.rows[static_cast<std::size_t>(cursor_)].id, "bind."))
            p.highlight = input::action_name(static_cast<input::Action>(id_number(p.rows[static_cast<std::size_t>(cursor_)].id)));
    }
    if (page_ == Page::Capture) {
        p.modal = fmt("controls.capture", {input::action_name(capture_)});
        p.modal_detail = tr("controls.capture.detail");
    }
    return f;
}

std::vector<std::string> Menu::lines() const {
    std::vector<std::string> out{"== " + title() + " =="};
    if (rail_) out.push_back("[tabs]");
    const auto all = rows();
    const int first = std::clamp(cursor_ - kVisibleRows + 1, 0, std::max(0, static_cast<int>(all.size()) - kVisibleRows));
    for (int i = first; i < static_cast<int>(all.size()) && i < first + kVisibleRows; ++i) {
        const Row &r = all[static_cast<std::size_t>(i)];
        std::string text = r.label, value = r.value;
        switch (r.kind) {
        case RowKind::Choice:
        case RowKind::Slider: value = "< " + value + " >"; break;
        case RowKind::Binding: value = r.value + (r.value2.empty() ? "" : " | " + r.value2); break;
        case RowKind::Header: text = "-- " + text + " --"; break;
        default: break;
        }
        out.push_back(std::string(i == cursor_ && !rail_ ? "> " : "  ") + text + (value.empty() ? "" : "  " + value));
    }
    if (page_ == Page::Saves && all.empty()) out.push_back("  " + tr("saves.none"));
    if (page_ == Page::Capture) out.push_back("? " + fmt("controls.capture", {input::action_name(capture_)}));
    if (!message_.empty()) out.push_back("! " + message_);
    return out;
}

} // namespace anypsp::menu
